@keyframes bp-spin { 
  0% { transform: rotate(0turn); }
  100% { transform: rotate(-1turn); }
}.bp-overlay { position: fixed; top: 0px; left: 0px; width: 100vw; height: 100vh; background: rgba(0, 0, 0, 0.35); z-index: 2147483647; display: flex; align-items: flex-end; justify-content: center; pointer-events: auto; cursor: not-allowed; font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif; }html[data-bp-ai-acting="true"] .bp-overlay, html[data-bp-ai-acting="mouse"] .bp-overlay { pointer-events: none !important; }.bp-glow-container { position: fixed; top: 0px; left: 0px; width: 100vw; height: 100vh; z-index: 2147483647; pointer-events: none; opacity: 1; }.bp-sharp-container { position: fixed; top: 0px; left: 0px; width: 100vw; height: 100vh; z-index: 2147483647; pointer-events: none; }.bp-glow-mask { position: absolute; inset: 0px; mask-image: radial-gradient(transparent 40%, black 75%); overflow: hidden; }.bp-sharp-mask { position: absolute; inset: 0px; padding: 2px; box-sizing: border-box; mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px); overflow: hidden; }.bp-gradient-spin { position: absolute; top: 50%; left: 50%; width: 200vmax; height: 200vmax; margin-top: -100vmax; margin-left: -100vmax; animation: 4s linear 0s infinite normal none running bp-spin; transform-origin: center center; }.bp-glow-spin { background-image: conic-gradient(rgb(173, 198, 255) 0%, rgba(0, 122, 255, 0.7) 10%, rgba(0, 91, 193, 0.3) 25%, transparent 40%, transparent 100%); filter: blur(60px); opacity: 0.7; }.bp-sharp-spin { background-image: conic-gradient(rgb(173, 198, 255) 0%, rgba(0, 122, 255, 0.9) 5%, rgba(0, 91, 193, 0.5) 15%, transparent 25%, transparent 100%); }.bp-action-bar-root, .bp-dialog-overlay { --bp-font-family: Inter, -apple-system, BlinkMacSystemFont, sans-serif; --bp-bg-glass: rgba(31, 31, 33, 0.7); --bp-border-glass: rgba(255, 255, 255, 0.1); --bp-shadow-primary: 0 12px 40px rgba(0, 0, 0, 0.3), inset 0 1px 1px rgba(255, 255, 255, 0.1); }.bp-action-bar-root { position: fixed; bottom: 48px; left: 50%; transform: translateX(-50%) translateY(0px); z-index: 2147483647; display: flex; align-items: center; padding: 10px 16px 10px 12px; gap: 14px; background: var(--bp-bg-glass); backdrop-filter: blur(40px) saturate(180%); border: 1px solid var(--bp-border-glass); border-radius: 9999px; box-shadow: var(--bp-shadow-primary); animation: 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal none running bp-slide-up; user-select: none; transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1); font-family: var(--bp-font-family); pointer-events: auto; cursor: default; }@keyframes bp-slide-up { 
  0% { transform: translateX(-50%) translateY(100px); opacity: 0; }
  100% { transform: translateX(-50%) translateY(0px); opacity: 1; }
}@keyframes orb-blink { 
  0%, 96%, 98% { transform: scaleY(1); }
  97% { transform: scaleY(0.1); }
}@keyframes neon-pulse { 
  0% { transform: scale(1); }
  50% { transform: scale(1.1); }
  100% { transform: scale(1); }
}@keyframes mesh-flow { 
  0% { background-position: 0% 0%; }
  50% { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}.bp-standard-wrapper { position: relative; width: 22px; height: 22px; display: flex; align-items: center; justify-content: center; }.bp-standard-orb { position: relative; width: 100%; height: 100%; border-radius: 50%; overflow: hidden; display: flex; align-items: center; justify-content: center; background-color: rgb(19, 19, 21); background-image: radial-gradient(circle at 0% 0%, rgba(0, 122, 255, 0.6) 0px, transparent 70%), radial-gradient(circle at 100% 100%, rgba(173, 198, 255, 0.6) 0px, transparent 70%), linear-gradient(135deg, rgba(0, 91, 193, 0.4) 0%, rgba(0, 122, 255, 0.4) 100%); background-size: 200% 200%; animation: 4s ease-in-out 0s infinite normal none running mesh-flow; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }.bp-orb-eyes { position: absolute; inset: 0px; display: flex; align-items: center; justify-content: center; gap: 3px; z-index: 2; transition: transform 0.1s ease-out; transform: translate(var(--eye-x, 0px), var(--eye-y, 0px)); }.bp-orb-eye { width: 4px; height: 4px; background: rgb(173, 198, 255); border-radius: 50%; animation: 4s ease 0s infinite normal none running orb-blink; box-shadow: rgba(173, 198, 255, 0.5) 0px 0px 4px; }.bp-orb-eyes.orb-typing { animation: 1s ease 0s infinite alternate none running orb-eyes-dart; }@keyframes orb-eyes-dart { 
  0% { transform: translate(calc(var(--eye-x, 0px) - 2px), var(--eye-y, 0px)); }
  100% { transform: translate(calc(var(--eye-x, 0px) + 2px), var(--eye-y, 0px)); }
}.bp-status-container { max-width: 250px; overflow: hidden; display: flex; align-items: center; }.bp-status-text { font-size: 14px; font-weight: 500; color: rgb(228, 226, 228); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: -0.01em; transition: opacity 0.2s; font-family: Inter, sans-serif; }.bp-divider { width: 1px; height: 20px; background: rgba(255, 255, 255, 0.1); border-radius: 1px; }.bp-button-group { display: flex; gap: 4px; }.bp-action-btn { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.2s; color: rgb(193, 198, 215); background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; padding: 0px; }.bp-action-btn:hover { background: rgba(255, 255, 255, 0.05); color: rgb(228, 226, 228); }.bp-action-btn:active { background: rgba(255, 255, 255, 0.1); }.bp-action-btn svg { width: 16px; height: 16px; stroke-width: 2; }.bp-btn-stop:hover { color: rgb(255, 180, 171); background: rgba(147, 0, 10, 0.2); }.bp-dialog-overlay { position: fixed; inset: 0px; z-index: 2147483647; display: flex; align-items: center; justify-content: center; pointer-events: auto; background: rgba(0, 0, 0, 0.7); backdrop-filter: blur(8px); animation: 0.2s ease-out 0s 1 normal none running bp-fade-in-fast; font-family: Inter, sans-serif; }@keyframes bp-fade-in-fast { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}.bp-dialog { background: rgb(19, 19, 21); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.6) 0px 20px 40px; padding: 24px; width: 300px; display: flex; flex-direction: column; gap: 12px; transform: scale(0.95); animation: 0.2s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal forwards running bp-pop-in; }@keyframes bp-pop-in { 
  100% { transform: scale(1); }
}.bp-dialog-title { font-size: 16px; font-weight: 600; color: rgb(173, 198, 255); margin: 0px; display: flex; align-items: center; gap: 8px; }.bp-dialog-desc { font-size: 14px; color: rgb(193, 198, 215); margin: 0px; line-height: 1.5; }.bp-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 12px; }.bp-dialog-btn { padding: 8px 16px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer; transition: 0.2s; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }.bp-dialog-btn-cancel { background: rgba(255, 255, 255, 0.1); color: rgb(193, 198, 215); }.bp-dialog-btn-cancel:hover { background: rgba(255, 255, 255, 0.15); color: rgb(228, 226, 228); }.bp-dialog-btn-stop { background: rgba(147, 0, 10, 0.3); color: rgb(255, 180, 171); }.bp-dialog-btn-stop:hover { background: rgba(147, 0, 10, 0.4); }.bp-badge { position: fixed; bottom: 20px; right: 20px; z-index: 2147483646; background: rgba(19, 19, 21, 0.85); backdrop-filter: blur(24px) saturate(180%); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 9999px; padding: 6px 14px 6px 10px; display: flex; align-items: center; gap: 10px; cursor: pointer; font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif; box-shadow: rgba(0, 0, 0, 0.4) 0px 10px 30px, rgba(255, 255, 255, 0.05) 0px 1px 1px inset; transition: 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); user-select: none; pointer-events: auto; }.bp-badge:hover { background: rgba(25, 25, 28, 0.95); border-color: rgba(0, 122, 255, 0.4); transform: translateY(-2px); box-shadow: rgba(0, 122, 255, 0.2) 0px 12px 35px, rgba(255, 255, 255, 0.05) 0px 1px 1px inset; }.bp-badge:active { transform: translateY(0px); }.bp-badge-title { font-weight: 600; font-size: 13px; color: rgb(228, 226, 228); letter-spacing: -0.01em; }.bp-badge-status { font-size: 10px; font-weight: 700; color: rgb(173, 198, 255); text-transform: uppercase; letter-spacing: 0.05em; background: rgba(0, 122, 255, 0.15); padding: 2px 8px; border-radius: 9999px; border: 1px solid rgba(0, 122, 255, 0.25); }.bp-chat-bubble { position: absolute; bottom: 130%; left: 23px; transform: translateX(-50%) translateY(10px); background: rgb(42, 42, 44); padding: 8px 12px; border-radius: 8px; color: rgb(228, 226, 228); font-size: 11px; font-weight: 500; font-family: var(--bp-font-family); box-shadow: rgba(0, 0, 0, 0.4) 0px 12px 24px, rgba(255, 255, 255, 0.05) 0px 0px 0px 1px; opacity: 0; pointer-events: auto; transition: 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); white-space: nowrap; display: flex; gap: 12px; align-items: center; }.bp-chat-bubble.visible { opacity: 1; transform: translateX(-50%) translateY(0px); }.bp-chat-bubble::after { content: ""; position: absolute; bottom: -4px; left: 50%; width: 10px; height: 10px; margin-left: -5px; background: rgb(42, 42, 44); box-shadow: rgba(255, 255, 255, 0.05) 1px 1px 0px; transform: rotate(45deg); }.bp-bubble-stop-btn { background: rgba(147, 0, 10, 0.3); color: rgb(255, 180, 171); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; padding: 4px 8px; border-radius: 4px; cursor: pointer; font-size: 10px; font-weight: 600; font-family: var(--bp-font-family); transition: background 0.2s; }.bp-bubble-stop-btn:hover { background: rgba(147, 0, 10, 0.5); }

